class Solution {
 bool prime(int x){if(x<2)return false;for(int d=2;1LL*d*d<=x;++d)if(x%d==0)return false;return true;}
public:
 int diagonalPrime(vector<vector<int>>& nums){int ans=0,n=nums.size();for(int i=0;i<n;++i){if(prime(nums[i][i]))ans=max(ans,nums[i][i]);if(prime(nums[i][n-1-i]))ans=max(ans,nums[i][n-1-i]);}return ans;}
};
